RNC_st.name='RNC'; 
RNC_st.lat=30.32;
RNC_st.lon=78.41;
RNC_st.alt=0000;
RNC_st.env='Mt';
RNC_st.footp='RB';
%%
% data imported via the import tool from matlab
 RNC_rd_h = importfile_AE_India("C:\github_trend\raw_data\Aethalometer_India\Aethalometer\RNC_2016-2026_Hour.csv", [2, Inf]);
RNC_rd_h.Properties.DimensionNames{1}='Time';
RNC_rd_h.Properties.VariableNames{2}='Ba1_A';
RNC_rd_h.Properties.VariableNames{3}='Ba2_A';
RNC_rd_h.Properties.VariableNames{4}='Ba3_A';
RNC_rd_h.Properties.VariableNames{5}='Ba4_A';
RNC_rd_h.Properties.VariableNames{6}='Ba5_A';
RNC_rd_h.Properties.VariableNames{7}='Ba6_A';
RNC_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(RNC_rd_h);
%%
RNC_rd=retime(RNC_rd_h,'daily',@nanmedian);
%%
datevec(RNC_rd.Time(1)) % begin in 2019 June,  %[output:7a3f5d0a]
datevec(RNC_rd.Time(end)) % end in 2024 august too short %[output:0c280ed0]
plotFigControl(RNC_rd,RNC_st.name);  %[output:7030742d] %[output:92f916c9] %[output:8a3db4cb] %[output:0941217c] %[output:81f161b9] %[output:7911ff20] %[output:977cd030] %[output:04cba172]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
RNC_cal=compute_exp_D(RNC_rd,names_abs,lambdaAE7); %[output:7c63b252] %[output:600ff552] %[output:829f7b86]
plotFigControl_cal(RNC_cal,RNC_st.name); %[output:61434ad4] %[output:15dee4cb] %[output:3ad61939]
%%
%HOMOGENEITY

break_RNC_abs_BP=change_point_analysis_Def(RNC_rd,names_abs,0.05,'RNC','Absorption'); %[output:6b7ee9f8] %[output:5a393386] %[output:85ed12d1] %[output:4eb1a59d] %[output:9f80f676] %[output:89fee263]
T_RNC_abs_BP=make_table_breakpoints_def(break_RNC_abs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:9a1c32f1]
break_RNC_expA_BP=change_point_analysis_Def(RNC_cal,names_expA,0.05,'RNC','Absorption exponent'); %[output:475d1e3e] %[output:364d3187] %[output:97cc50b7] %[output:5b935826]
T_RNC_expA_BP=make_table_breakpoints_def(break_RNC_expA_BP);




